import test from 'node:test';import assert from 'node:assert/strict';
import {suitPowers,allSuitPowers,normalizeSuit,activateSuit,suitPowerFor,suitSubject,suitPowerView,suitArt,suitArtKeys,suitOverlay,crewDescription,pendingAstronaut} from '../src/suits.js';import {objects} from '../src/data.js';
test('all crew are astronauts, Lucas is French and the Chinese astronomy profile awaits identity',()=>{assert.equal(crewDescription('Lucas Turner'),'Astronaut • France');assert.equal(crewDescription('Sumati Suri'),'Astronaut • India');assert.equal(crewDescription('Lilja Jónsdóttir'),'Astronaut • Iceland');assert.equal(crewDescription('Alex Thompson'),'Astronaut');assert.equal(pendingAstronaut.country,'China');assert.equal(pendingAstronaut.gender,'male');assert.equal(pendingAstronaut.specialization,'Astronomy and Astrophysics');assert.equal(pendingAstronaut.name,null);assert.equal(pendingAstronaut.suit,null)});
test('nine suit powers reveal real target positions and have three repeatable illustrated steps',()=>{assert.equal(allSuitPowers.length,9);for(const [name,powers]of Object.entries(suitPowers))for(const power of powers){assert.equal(suitPowerFor(name,power.id),power);const pictures=new Set();for(let step=0;step<3;step++){const v=suitPowerView(name,power.id,step,{zone:'grounds',target:'plant'});assert.ok(v.text&&v.heading);assert.ok(suitArtKeys.includes(v.art));pictures.add(suitArt(v.art));}assert.equal(pictures.size,3,power.id);assert.equal(suitPowerView(name,power.id,3).step,0);const svg=suitOverlay(power,'grounds');assert.ok(svg.includes('<svg'));if(suitSubject(power,objects.find(o=>o.id==='plant')))assert.ok(svg.includes('cx="220" cy="245"'));}assert.equal(suitPowerView('Alex Thompson','bio-vision'),null);assert.equal(suitSubject(allSuitPowers[0],objects.find(o=>o.id==='home')),false);assert.equal(suitSubject(allSuitPowers[0],objects.find(o=>o.id==='rock')),false)});
test('distance and environment tools reflect the selected map and current training settings',()=>{const v=suitPowerView('Lilja Jónsdóttir','measure-map',0,{zone:'grounds',target:'rock',position:[200,500]});assert.match(v.text,new RegExp(Math.round(Math.hypot(180,-325))+' training units'));assert.match(v.text,/not real metres/);assert.equal(suitPowerView('Lilja Jónsdóttir','measure-map',0,{zone:'farm',target:'rock'}).target,null);assert.match(suitPowerView('Sumati Suri','environmental-survey',1,{farm:{shade:true,vent:false}}).text,/shade on, vent closed/);const ocean=suitOverlay(allSuitPowers[2],'aquatic','lake');assert.ok(!ocean.includes('cx="800" cy="300"'));const deep=suitOverlay(allSuitPowers[2],'dig','lake',1);assert.ok(!deep.includes('data-suit-target="dig-quartz"'))});
test('power activation is validated and persistent history is idempotent without consuming resources',()=>{const first=normalizeSuit();let s=activateSuit(first,'Lucas Turner','bio-vision');s=activateSuit(s,'Lucas Turner','bio-vision');assert.deepEqual(first,{overlay:null,records:[]});assert.deepEqual(s.records,['bio-vision']);assert.deepEqual(activateSuit(s,'Lucas Turner','geometry-builder'),s);assert.deepEqual(normalizeSuit({overlay:'bad',records:['bad','bio-vision','bio-vision']}),{overlay:null,records:['bio-vision']});assert.match(suitPowerView('Lucas Turner','xeno-analysis',1).text,/No extraterrestrial life is confirmed/)});
